import React, { useState, useEffect } from 'react';

const API_URL = 'http://127.0.0.1:8000/api';

function ModelManagement() {
    const [models, setModels] = useState([]);

    useEffect(() => {
        // This is a placeholder for fetching models from MLflow
        fetch(`${API_URL}/mlflow/models`)
            .then(res => res.json())
            .then(data => setModels(data))
            .catch(err => console.error("Failed to fetch models", err));
    }, []);

    return (
        <div className="card">
            <h2>Model Management (via MLflow)</h2>
            <p>This section will allow you to view, manage, and deploy models from the MLflow Model Registry.</p>
            <button disabled>Retrain Model (Future)</button>
            <h3>Registered Models</h3>
            <table>
                <thead>
                    <tr>
                        <th>Name</th>
                        <th>Version</th>
                        <th>Stage</th>
                    </tr>
                </thead>
                <tbody>
                    {models.map(m => <tr key={m.name}><td>{m.name}</td><td>{m.version}</td><td>{m.stage}</td></tr>)}
                </tbody>
            </table>
        </div>
    );
}

export default ModelManagement;
